-- Supplier Reliability Engine seed data (SQLite dialect).
-- Foreign keys are declared but enforcement is off during load because the
-- dataset deliberately contains labelled anomalies (see ground_truth/).
-- After loading run: PRAGMA foreign_key_check;  -> only SHIPMENT_NO_PO rows appear.
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS "Supplier";
CREATE TABLE "Supplier" (
  "supplier_id" TEXT NOT NULL,
  "supplier_name" TEXT,
  "category" TEXT,
  "country" TEXT,
  "supplier_tier" TEXT,
  "onboarding_date" TEXT,
  "status" TEXT,
  PRIMARY KEY ("supplier_id")
);
DROP TABLE IF EXISTS "Site";
CREATE TABLE "Site" (
  "site_id" TEXT NOT NULL,
  "supplier_id" TEXT,
  "site_seq" INTEGER,
  "site_name" TEXT,
  "site_type" TEXT,
  "country" TEXT,
  "address" TEXT,
  "effective_from" TEXT,
  "status" TEXT,
  PRIMARY KEY ("site_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id")
);
DROP TABLE IF EXISTS "Contract";
CREATE TABLE "Contract" (
  "contract_id" TEXT NOT NULL,
  "supplier_id" TEXT,
  "site_id" TEXT,
  "start_date" TEXT,
  "end_date" TEXT,
  "currency" TEXT,
  "payment_terms_days" INTEGER,
  "price_tolerance_pct" REAL,
  "capacity_units_month" INTEGER,
  "certification_type" TEXT,
  "certification_expiry_date" TEXT,
  "last_audit_date" TEXT,
  "last_audit_score" REAL,
  "status" TEXT,
  PRIMARY KEY ("contract_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id"),
  FOREIGN KEY ("site_id") REFERENCES "Site" ("site_id")
);
DROP TABLE IF EXISTS "PurchaseOrder";
CREATE TABLE "PurchaseOrder" (
  "po_id" TEXT NOT NULL,
  "supplier_id" TEXT,
  "site_id" TEXT,
  "contract_id" TEXT,
  "planner_id" TEXT,
  "order_date" TEXT,
  "required_date" TEXT,
  "currency" TEXT,
  "total_amount" REAL,
  "line_count" INTEGER,
  "status" TEXT,
  PRIMARY KEY ("po_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id"),
  FOREIGN KEY ("site_id") REFERENCES "Site" ("site_id"),
  FOREIGN KEY ("contract_id") REFERENCES "Contract" ("contract_id")
);
DROP TABLE IF EXISTS "POLine";
CREATE TABLE "POLine" (
  "po_line_id" TEXT NOT NULL,
  "po_id" TEXT,
  "line_number" INTEGER,
  "item_id" TEXT,
  "ordered_qty" INTEGER,
  "unit_price" REAL,
  "line_total" REAL,
  PRIMARY KEY ("po_line_id"),
  FOREIGN KEY ("po_id") REFERENCES "PurchaseOrder" ("po_id")
);
DROP TABLE IF EXISTS "POStatusEvent";
CREATE TABLE "POStatusEvent" (
  "po_event_id" TEXT NOT NULL,
  "po_id" TEXT,
  "event_seq" INTEGER,
  "status" TEXT,
  "event_timestamp" TEXT,
  "trigger" TEXT,
  PRIMARY KEY ("po_event_id"),
  FOREIGN KEY ("po_id") REFERENCES "PurchaseOrder" ("po_id")
);
DROP TABLE IF EXISTS "Shipment";
CREATE TABLE "Shipment" (
  "shipment_id" TEXT NOT NULL,
  "po_id" TEXT,
  "supplier_id" TEXT,
  "site_id" TEXT,
  "carrier_id" TEXT,
  "transport_mode" TEXT,
  "receiving_warehouse_id" TEXT,
  "created_date" TEXT,
  "dispatch_date" TEXT,
  "delivery_date" TEXT,
  "shipped_qty_total" INTEGER,
  "status" TEXT,
  PRIMARY KEY ("shipment_id"),
  FOREIGN KEY ("po_id") REFERENCES "PurchaseOrder" ("po_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id"),
  FOREIGN KEY ("site_id") REFERENCES "Site" ("site_id")
);
DROP TABLE IF EXISTS "ShipmentLine";
CREATE TABLE "ShipmentLine" (
  "shipment_line_id" TEXT NOT NULL,
  "shipment_id" TEXT,
  "po_line_id" TEXT,
  "shipped_qty" INTEGER,
  PRIMARY KEY ("shipment_line_id"),
  FOREIGN KEY ("shipment_id") REFERENCES "Shipment" ("shipment_id"),
  FOREIGN KEY ("po_line_id") REFERENCES "POLine" ("po_line_id")
);
DROP TABLE IF EXISTS "DeliveryEvent";
CREATE TABLE "DeliveryEvent" (
  "delivery_event_id" TEXT NOT NULL,
  "shipment_id" TEXT,
  "event_seq" INTEGER,
  "event_type" TEXT,
  "event_timestamp" TEXT,
  "recorded_by" TEXT,
  "location" TEXT,
  PRIMARY KEY ("delivery_event_id"),
  FOREIGN KEY ("shipment_id") REFERENCES "Shipment" ("shipment_id")
);
DROP TABLE IF EXISTS "Inspection";
CREATE TABLE "Inspection" (
  "inspection_id" TEXT NOT NULL,
  "shipment_id" TEXT,
  "lot_number" INTEGER,
  "supplier_id" TEXT,
  "inspector_id" TEXT,
  "inspection_date" TEXT,
  "inspected_qty" INTEGER,
  "accepted_qty" INTEGER,
  "rejected_qty" INTEGER,
  "defect_code" TEXT,
  "result" TEXT,
  PRIMARY KEY ("inspection_id"),
  FOREIGN KEY ("shipment_id") REFERENCES "Shipment" ("shipment_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id")
);
DROP TABLE IF EXISTS "Invoice";
CREATE TABLE "Invoice" (
  "invoice_id" TEXT NOT NULL,
  "shipment_id" TEXT,
  "po_id" TEXT,
  "supplier_id" TEXT,
  "invoice_date" TEXT,
  "due_date" TEXT,
  "currency" TEXT,
  "expected_amount" REAL,
  "invoiced_amount" REAL,
  "variance_amount" REAL,
  "variance_pct" REAL,
  "match_status" TEXT,
  PRIMARY KEY ("invoice_id"),
  FOREIGN KEY ("shipment_id") REFERENCES "Shipment" ("shipment_id"),
  FOREIGN KEY ("po_id") REFERENCES "PurchaseOrder" ("po_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id")
);
DROP TABLE IF EXISTS "RiskSignal";
CREATE TABLE "RiskSignal" (
  "risk_signal_id" TEXT NOT NULL,
  "supplier_id" TEXT,
  "risk_type" TEXT,
  "severity" TEXT,
  "signal_timestamp" TEXT,
  "source" TEXT,
  "resolved_timestamp" TEXT,
  "status" TEXT,
  PRIMARY KEY ("risk_signal_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id")
);
DROP TABLE IF EXISTS "SupplierScore";
CREATE TABLE "SupplierScore" (
  "score_id" TEXT NOT NULL,
  "score_run_id" TEXT,
  "supplier_id" TEXT,
  "model_version" TEXT,
  "score_timestamp" TEXT,
  "observation_start" TEXT,
  "max_source_date" TEXT,
  "delivery_score" REAL,
  "quality_score" REAL,
  "cost_score" REAL,
  "capacity_score" REAL,
  "compliance_score" REAL,
  "disruption_score" REAL,
  "data_coverage_pct" REAL,
  "components_missing" TEXT,
  "reliability_score" REAL,
  "reliability_tier" TEXT,
  "decision" TEXT,
  "top_drivers" TEXT,
  "open_high_risks" INTEGER,
  "source_record_counts" TEXT,
  PRIMARY KEY ("score_id"),
  FOREIGN KEY ("supplier_id") REFERENCES "Supplier" ("supplier_id")
);
DROP TABLE IF EXISTS "SupplierScoreComponent";
CREATE TABLE "SupplierScoreComponent" (
  "score_component_id" TEXT NOT NULL,
  "score_id" TEXT,
  "component" TEXT,
  "status" TEXT,
  "numerator" REAL,
  "denominator" REAL,
  "denominator_definition" TEXT,
  "metric_value" REAL,
  "adjustment" REAL,
  "formula" TEXT,
  "component_score" REAL,
  "base_weight" REAL,
  "effective_weight" REAL,
  "weighted_contribution" REAL,
  PRIMARY KEY ("score_component_id"),
  FOREIGN KEY ("score_id") REFERENCES "SupplierScore" ("score_id")
);
COMMIT;
